import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Meilisearch: Local vs Cloud","description":"","frontmatter":{},"headers":[],"relativePath":"guide/meilisearch-local-vs-cloud.md","filePath":"guide/meilisearch-local-vs-cloud.md","lastUpdated":null}'),l={name:"guide/meilisearch-local-vs-cloud.md"};function o(n,e,d,r,c,h){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="meilisearch-local-vs-cloud" tabindex="-1">Meilisearch: Local vs Cloud <a class="header-anchor" href="#meilisearch-local-vs-cloud" aria-label="Permalink to &quot;Meilisearch: Local vs Cloud&quot;">​</a></h1><p>Geomilli is designed to run seamlessly against a <strong>self-hosted local Meilisearch container</strong> or a fully managed <strong>Meilisearch Cloud</strong> cluster with zero application code changes.</p><hr><h2 id="architecture-comparison" tabindex="-1">Architecture Comparison <a class="header-anchor" href="#architecture-comparison" aria-label="Permalink to &quot;Architecture Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Feature</th><th style="text-align:left;">Local Docker Meilisearch</th><th style="text-align:left;">Meilisearch Cloud</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Hosting Model</strong></td><td style="text-align:left;">Container on host machine (<code>getmeili/meilisearch:v1.13</code>)</td><td style="text-align:left;">Managed multi-tenant or dedicated cluster</td></tr><tr><td style="text-align:left;"><strong>Default Host</strong></td><td style="text-align:left;"><code>http://127.0.0.1:7700</code> or <code>http://meilisearch:7700</code></td><td style="text-align:left;"><code>https://ms-xxxx.region.meilisearch.io</code></td></tr><tr><td style="text-align:left;"><strong>API Key</strong></td><td style="text-align:left;">Configurable (<code>masterKey123</code> in <code>.env.example</code>)</td><td style="text-align:left;">Cloud Dashboard API Key</td></tr><tr><td style="text-align:left;"><strong>Storage</strong></td><td style="text-align:left;">Local Docker volume (<code>meili_data</code>)</td><td style="text-align:left;">Cloud SSD / High-IOPS managed storage</td></tr><tr><td style="text-align:left;"><strong>High Availability</strong></td><td style="text-align:left;">Single node</td><td style="text-align:left;">Auto-failover &amp; regional replicas</td></tr><tr><td style="text-align:left;"><strong>SSL / TLS</strong></td><td style="text-align:left;">Self-managed reverse proxy (e.g. Caddy/Nginx)</td><td style="text-align:left;">Automatic HTTPS &amp; TLS 1.3</td></tr></tbody></table><hr><h2 id="_1-local-meilisearch-default" tabindex="-1">1. Local Meilisearch (Default) <a class="header-anchor" href="#_1-local-meilisearch-default" aria-label="Permalink to &quot;1. Local Meilisearch (Default)&quot;">​</a></h2><p>In standard local mode, Docker Compose boots Meilisearch alongside <code>geomilli-api</code>, <code>geomilli-harvester</code>, and <code>geomilli-studio</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><h3 id="environment-settings-env" tabindex="-1">Environment Settings (<code>.env</code>): <a class="header-anchor" href="#environment-settings-env" aria-label="Permalink to &quot;Environment Settings (`.env`):&quot;">​</a></h3><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MEILI_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://meilisearch:7700</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MEILI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">masterKey123</span></span></code></pre></div><p>Within the Docker network, services communicate over <code>http://meilisearch:7700</code>. From your host workstation, Meilisearch is reachable at <code>http://localhost:7700</code>.</p><hr><h2 id="_2-meilisearch-cloud-deployment" tabindex="-1">2. Meilisearch Cloud Deployment <a class="header-anchor" href="#_2-meilisearch-cloud-deployment" aria-label="Permalink to &quot;2. Meilisearch Cloud Deployment&quot;">​</a></h2><p>When deploying to production with Meilisearch Cloud:</p><ol><li>Create a project at <a href="https://cloud.meilisearch.com" target="_blank" rel="noreferrer">cloud.meilisearch.com</a>.</li><li>Note your <strong>URL</strong> (e.g., <code>https://ms-981273abc.sfo.meilisearch.io</code>) and <strong>Default Admin API Key</strong>.</li><li>Update your <code>.env</code> file:<div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MEILI_HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://ms-981273abc.sfo.meilisearch.io</span></span>\n<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">MEILI_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">meili_cloud_admin_key_xxxxxxxxxxxxx</span></span></code></pre></div></li><li>Start the stack using the cloud compose override:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.cloud.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div></li></ol><h3 id="what-docker-compose-cloud-yml-does" tabindex="-1">What <code>docker-compose.cloud.yml</code> Does: <a class="header-anchor" href="#what-docker-compose-cloud-yml-does" aria-label="Permalink to &quot;What `docker-compose.cloud.yml` Does:&quot;">​</a></h3><ul><li><strong>Disables the local <code>meilisearch</code> container</strong>: Frees up local CPU, RAM, and port <code>7700</code>.</li><li><strong>Reconfigures <code>geomilli-api</code> and <code>geomilli-harvester</code></strong>: Connects directly to the external Meilisearch Cloud endpoint over secure HTTPS.</li><li><strong>Adjusts health dependencies</strong>: Allows the API and harvester to boot immediately without waiting for a local container health check.</li></ul><hr><h2 id="_3-quota-indexing-considerations-for-cloud" tabindex="-1">3. Quota &amp; Indexing Considerations for Cloud <a class="header-anchor" href="#_3-quota-indexing-considerations-for-cloud" aria-label="Permalink to &quot;3. Quota &amp; Indexing Considerations for Cloud&quot;">​</a></h2><p>When indexing large regions into Meilisearch Cloud:</p><ul><li>Ensure your cloud plan has sufficient document quota (Belgium produces ~180k places; Europe produces ~30M places; Planet produces ~120M places).</li><li>The shadow index atomic swap (<code>swapIndexes</code>) operates identically on Cloud and Local, ensuring zero-downtime upgrades.</li></ul>',22)])])}const u=t(l,[["render",o]]);export{g as __pageData,u as default};
